CREATE SCHEMA IF NOT EXISTS security_ops;
CREATE OR REPLACE FUNCTION security_ops.severity_rank(value text)RETURNS integer IMMUTABLE LANGUAGE sql AS $$SELECT CASE value WHEN 'critical' THEN 5 WHEN 'high' THEN 4 WHEN 'medium' THEN 3 WHEN 'low' THEN 2 ELSE 1 END$$;
CREATE TABLE security_ops.assets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,asset_key text NOT NULL,asset_type text NOT NULL CHECK(asset_type IN('repository','image','service','api','dependency','infrastructure')),owner_team text NOT NULL,internet_exposed boolean NOT NULL DEFAULT false,criticality text NOT NULL CHECK(criticality IN('tier1','tier2','tier3')),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,asset_key));
CREATE TABLE security_ops.scan_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,scanner text NOT NULL,scope text NOT NULL,state text NOT NULL CHECK(state IN('queued','running','passed','failed','cancelled')),source_revision text NOT NULL,findings_count integer NOT NULL DEFAULT 0,critical_count integer NOT NULL DEFAULT 0,high_count integer NOT NULL DEFAULT 0,evidence_hash text,started_at timestamptz,finished_at timestamptz,created_at timestamptz NOT NULL DEFAULT clock_timestamp());CREATE INDEX security_scan_queue_idx ON security_ops.scan_runs(tenant_id,state,created_at DESC);
CREATE TABLE security_ops.vulnerabilities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,source text NOT NULL CHECK(source IN('sast','sca','secret','container','iac','dast','pentest')),component text NOT NULL,component_version text NOT NULL,severity text NOT NULL CHECK(severity IN('critical','high','medium','low','informational')),severity_rank integer NOT NULL,cve text,cvss numeric(3,1) NOT NULL DEFAULT 0,state text NOT NULL CHECK(state IN('open','triaged','fixing','verification','resolved','accepted','false_positive')),known_exploited boolean NOT NULL DEFAULT false,internet_exposed boolean NOT NULL DEFAULT false,fix_available boolean NOT NULL DEFAULT false,due_at timestamptz NOT NULL,reported_by uuid NOT NULL,assigned_to uuid,resolved_at timestamptz,detected_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,source,component,component_version,cve));CREATE INDEX security_vulnerability_queue_idx ON security_ops.vulnerabilities(tenant_id,state,known_exploited DESC,severity_rank DESC,due_at);
CREATE TABLE security_ops.sbom_releases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,release_version text NOT NULL,source_revision text NOT NULL,format text NOT NULL CHECK(format='CycloneDX'),spec_version text NOT NULL,component_count integer NOT NULL CHECK(component_count>0),document_hash text NOT NULL,object_key text NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,release_version));
CREATE TABLE security_ops.provenance_attestations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,release_version text NOT NULL,subject_digest text NOT NULL,builder_id text NOT NULL,source_revision text NOT NULL,signature_valid boolean NOT NULL,materials_verified boolean NOT NULL,evidence jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,subject_digest));
CREATE TABLE security_ops.exceptions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,vulnerability_id uuid NOT NULL REFERENCES security_ops.vulnerabilities(id),reason text NOT NULL,compensating_controls jsonb NOT NULL,requested_by uuid NOT NULL,approved_by uuid NOT NULL CHECK(approved_by<>requested_by),expires_at timestamptz NOT NULL,state text NOT NULL CHECK(state IN('active','expired','revoked')),created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE security_ops.pentest_engagements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,title text NOT NULL,environment text NOT NULL CHECK(environment='staging'),targets jsonb NOT NULL,rules_of_engagement jsonb NOT NULL,emergency_contact_hash text NOT NULL,state text NOT NULL CHECK(state IN('planned','authorized','running','reporting','closed','cancelled')),requested_by uuid NOT NULL,approved_by uuid NOT NULL CHECK(approved_by<>requested_by),starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,report_hash text,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE security_ops.daily_metrics(tenant_id uuid NOT NULL,metric_date date NOT NULL,assets_total integer NOT NULL DEFAULT 0,critical_open integer NOT NULL DEFAULT 0,high_open integer NOT NULL DEFAULT 0,known_exploited_open integer NOT NULL DEFAULT 0,overdue_open integer NOT NULL DEFAULT 0,sbom_coverage_bps integer NOT NULL DEFAULT 0,provenance_coverage_bps integer NOT NULL DEFAULT 0,last_scan_at timestamptz,PRIMARY KEY(tenant_id,metric_date));
CREATE OR REPLACE FUNCTION security_ops.evidence_append_only()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'security evidence is append only';END$$;CREATE TRIGGER security_provenance_append_only BEFORE UPDATE OR DELETE ON security_ops.provenance_attestations FOR EACH ROW EXECUTE FUNCTION security_ops.evidence_append_only();
ALTER TABLE security_ops.assets ENABLE ROW LEVEL SECURITY;ALTER TABLE security_ops.scan_runs ENABLE ROW LEVEL SECURITY;ALTER TABLE security_ops.vulnerabilities ENABLE ROW LEVEL SECURITY;ALTER TABLE security_ops.sbom_releases ENABLE ROW LEVEL SECURITY;ALTER TABLE security_ops.provenance_attestations ENABLE ROW LEVEL SECURITY;ALTER TABLE security_ops.exceptions ENABLE ROW LEVEL SECURITY;ALTER TABLE security_ops.pentest_engagements ENABLE ROW LEVEL SECURITY;ALTER TABLE security_ops.daily_metrics ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation_security_assets ON security_ops.assets USING(tenant_id=current_setting('app.current_tenant_id')::uuid)WITH CHECK(tenant_id=current_setting('app.current_tenant_id')::uuid);CREATE POLICY tenant_isolation_security_scans ON security_ops.scan_runs USING(tenant_id=current_setting('app.current_tenant_id')::uuid)WITH CHECK(tenant_id=current_setting('app.current_tenant_id')::uuid);CREATE POLICY tenant_isolation_security_vulnerabilities ON security_ops.vulnerabilities USING(tenant_id=current_setting('app.current_tenant_id')::uuid)WITH CHECK(tenant_id=current_setting('app.current_tenant_id')::uuid);CREATE POLICY tenant_isolation_security_sbom ON security_ops.sbom_releases USING(tenant_id=current_setting('app.current_tenant_id')::uuid)WITH CHECK(tenant_id=current_setting('app.current_tenant_id')::uuid);CREATE POLICY tenant_isolation_security_provenance ON security_ops.provenance_attestations USING(tenant_id=current_setting('app.current_tenant_id')::uuid)WITH CHECK(tenant_id=current_setting('app.current_tenant_id')::uuid);CREATE POLICY tenant_isolation_security_exceptions ON security_ops.exceptions USING(tenant_id=current_setting('app.current_tenant_id')::uuid)WITH CHECK(tenant_id=current_setting('app.current_tenant_id')::uuid);CREATE POLICY tenant_isolation_security_pentest ON security_ops.pentest_engagements USING(tenant_id=current_setting('app.current_tenant_id')::uuid)WITH CHECK(tenant_id=current_setting('app.current_tenant_id')::uuid);CREATE POLICY tenant_isolation_security_metrics ON security_ops.daily_metrics USING(tenant_id=current_setting('app.current_tenant_id')::uuid)WITH CHECK(tenant_id=current_setting('app.current_tenant_id')::uuid);
